changeSet.sql:
drop TABLE if exists ACCOUNTING_PERIOD;
create masking policy if not exists name_mask as (val string) returns string -> case when current_role() in ('SYSADMIN') then val else concat(substr(val, 0, 2), '******') end;
create or replace view ACCOUNTING_ANALYTICS.VW_RECEIPT_DETAIL_REPORT( CONTROL, BATCH, PERIOD, DATE, DATE_YEAR, DATE_MONTH, DATE_DAY, ACCOUNTING_PERIOD, PERSONNAME WITH MASKING POLICY ACCOUNTING_ANALYTICS.NAME_MASK, PERSONCODE, PERSONSTATUS, PROPERTY, PROPERTYCODE, MARKET, OP, DEPOSITNUM, CASHACCT, AMOUNT, REFERENCE, CHECKNUM, NOTES, MODULECREATEDBY, CREATEDBY, CREATEDDATE, MODIFIEDBY, MODIFIEDDATE ) as Select Control, Batch, Period, DATEOCCURED as DATE, Date_Year, Date_Month, Date_Day, Accounting_Period, PersonName, PersonCode, PersonStatus, Property, PropertyCode, Market, OP, DepositNum, CashAcct, AMOUNT, Reference, CheckNum, Notes, ModuleCreatedBy, CreatedBy, CreatedDate, ModifiedBy, ModifiedDate FROM YARDI_DBO.TRANSRECEIPT;
